function pagination(p,key='page',prefix=''){let pages=Math.max(1,Math.ceil((p.total??0)/per));st[key]=Math.min(st[key]||0,pages-1);return '<div class="ic-pagination"><span>Page '+(st[key]+1)+' of '+pages+' · '+(p.total===null?'Total unavailable':p.total+' records')+'</span><div>'+btn('Previous',prefix?prefix+'prev':'prev-page','ic-ghost',st[key]===0)+btn('Next',prefix?prefix+'next':'next-page','ic-ghost',st[key]>=pages-1)+'</div></div>';}
