function filterPanel(options){return btn(icon('filter',14)+' Filters'+(st.filter==='all'?'':' (1)'),'toggle-filters','ic-filter-toggle',false,'aria-expanded="'+st.filtersOpen+'" aria-controls="ic-filter-panel"')+(st.filtersOpen?'<div class="ic-filter-panel" id="ic-filter-panel"><label>Show<select data-ui-state="true" data-action="filter" name="filter">'+options.map(opt=>'<option value="'+E(opt)+'" '+(st.filter===opt?'selected':'')+'>'+E(opt==='all'?'All':opt)+'</option>').join('')+'</select></label></div>':'');}
