const prompt='In the TrialAgents Investor CRM, read only the authorized saved investor, contact, opportunity and research brief records for the selected round. Identify new public investor focus, recent fund activity and relevant financing signals using reliable date-stamped primary sources. Match on sector, stage, geography and ticket range, deduplicate by investor identity and source URL, then propose a sourced candidate finding for human review. Never infer a signed commitment, make up a contact, send an outreach email, or write without the exact scoped authorization. Missing records, partial coverage or denied access must be reported as blocked/partial rather than no_update. An optional recurring monitor is configured only through platform Automations after app save, not here.';
function findingCard(r){const names=Object.fromEntries(roleFields.findings.map(f=>[f[0],f[1]]));return '<div class="ic-finding"><div>'+columns('findings').map(k=>'<div class="ic-finding-field"><small>'+E(names[k])+': </small>'+(k==='status'?pill(r.data[k],r.data[k]==='Approved'?'positive':''):k==='name'?'<strong>'+E(r.data[k])+'</strong>':E(displayValue('findings',k,r.data[k])))+'</div>').join('')+'<p>'+E(r.data.relevance||'')+'</p></div><div>'+btn('Edit','edit:findings:'+r.id,'ic-mini')+' '+btn('Add investor','research-add:'+r.id,'ic-mini',!allow('investors',['name']))+'</div></div>';}
function researchScreen(){const pp=browserPage('findings'),briefs=browserPage('briefs');return pageHeader('Investor research','Evidence-backed leads, with reviewed additions—not automatic outreach',btn(icon('plus',15)+' New research brief','add:briefs','ic-primary',!allow('briefs',['name'])))+quality(['briefs','findings','investors'])+'<div class="ic-research-grid"><section class="ic-card"><div class="ic-card-top"><h2>Research briefs</h2>'+pill(briefs.total!==null?briefs.total+' saved':'Coverage unavailable','soft')+'</div>'+(briefs.rows.length?briefs.rows.map(r=>'<div class="ic-brief"><strong>'+E(r.data.name)+'</strong><p>'+E(r.data.sector)+' · '+E(r.data.geography||'All regions')+' · '+E(r.data.stage_focus||'All stages')+'</p>'+btn('Edit','edit:briefs:'+r.id,'ic-mini')+'</div>').join(''):'<div class="ic-empty">'+(briefs.issue?'Research briefs unavailable: '+E(briefs.issue):'No saved research briefs on this page. Add a brief with target focus and exclusions.')+'</div>')+pagination(briefs,'briefPage','brief-')+'</section><section class="ic-card ic-card-dark"><span class="ic-upper">Research handoff</span><h2>Find fitting capital, with evidence.</h2><p>Use ChatGPT for public research, save reviewed findings in TrialAgents, and approve investor directory additions separately.</p>'+btn(st.promptOpen?'Hide instructions':'View ChatGPT instructions','toggle-prompt','ic-on-dark')+(st.promptOpen?'<div class="ic-prompt">'+E(prompt)+'</div>':'')+'<small>Runs and optional email are managed in platform Automations.</small></section></div><section class="ic-card" style="margin-top:18px;padding:15px"><div class="ic-card-top"><h2>Saved research findings</h2>'+btn('Add finding','add:findings','ic-outline',!allow('findings',['name']))+'</div><div class="ic-findings">'+(pp.rows.length?pp.rows.map(r=>findingCard(r)).join(''):'<div class="ic-empty">'+(pp.issue?'Findings unavailable: '+E(pp.issue):'No findings on this page. A research brief does not run ChatGPT automatically.')+'</div>')+'</div>'+pagination(pp)+'</section>';}
function fieldInput(role,f,d){const [key,label,kind,required,values]=f;if(key==='archived')return '';let val=d?.[key]??'',options=values;const relation=kind.startsWith('relation-');if(relation){const target=kind.slice(9);const rs=readAll(target);options=rs.rows.map(x=>[x.id,x.data.name]);}else if(kind==='select')options=values.map(x=>[x,x]);
 let html=options?'<select name="'+E(key)+'" data-action="editor:'+E(key)+'" data-ui-state="true" '+(required?'required':'')+'><option value="">Choose…</option>'+options.map(a=>'<option value="'+E(a[0])+'" '+(String(a[0])===String(val)?'selected':'')+'>'+E(a[1])+'</option>').join('')+'</select>':kind==='longtext'?'<textarea name="'+E(key)+'" data-action="editor:'+E(key)+'" data-ui-state="true" rows="3">'+E(val)+'</textarea>':'<input name="'+E(key)+'" type="'+(kind==='number'||kind==='money'?'number':kind==='date'?'date':'text')+'" value="'+E(val)+'" data-ui-state="true" data-action="editor:'+E(key)+'" '+(kind==='money'||kind==='number'?'step="any" min="0"':'')+' '+(required?'required':'')+'>';const locked=!allow(role,[key]);if(locked)html=html.replace(/<(input|select|textarea) /,'<$1 disabled ');return '<label class="ic-field '+(kind==='longtext'?'ic-field-wide':'')+'"><span>'+E(label)+(required?' <b>*</b>':'')+(locked?' (read only)':'')+'</span>'+html+'</label>';}
function editorModal(){if(!st.editor)return '';const d=st.editor,field=roleFields[d.role]||[],isInteraction=d.role==='interactions';return '<div class="ic-overlay"><section class="ic-drawer" role="dialog" aria-modal="true" aria-label="'+E(d.mode)+' '+E(d.role)+'"><div class="ic-drawer-head"><div><h2>'+E(d.mode==='edit'?'Edit':d.mode==='create'?'New':'Duplicate')+' '+E(d.role.replace(/s$/,''))+'</h2><p>Exact changes are reviewed by TrialAgents before saving.</p></div>'+btn(icon('close',19),'cancel-editor','ic-icon-btn')+'</div><form class="ic-drawer-form" data-action="'+(isInteraction?'save-interaction-plus':'save-editor')+'"><div class="ic-drawer-fields">'+field.filter(f=>f[0]!=='archived').map(f=>fieldInput(d.role,f,d.draft)).join('')+(isInteraction?'<div class="ic-field-wide ic-form-sep"><strong>Optional next action</strong><p>Create a linked open task in the same reviewed proposal.</p></div><label class="ic-field ic-field-wide"><span>Follow-up action title</span><input name="followup_title" type="text" data-ui-state="true" data-action="editor:followup_title" value="'+E(d.draft.followup_title||'')+'"></label><label class="ic-field"><span>Follow-up due</span><input name="followup_due" type="date" data-ui-state="true" data-action="editor:followup_due" value="'+E(d.draft.followup_due||'')+'"></label>':'')+'</div><div class="ic-drawer-foot">'+btn('Ignore','cancel-editor','ic-outline')+(d.mode==='edit'?btn('Archive','delete:'+d.role+':'+d.id,'ic-outline',!allow(d.role,['archived'])):'')+'<button class="ic-btn ic-primary" type="submit" '+(!allow(d.role,['name'])?'disabled':'')+'>Review '+(d.mode==='edit'?'changes':'creation')+'</button></div></form></section></div>';}
function deleteModal(){if(!st.deleteConfirm)return '';return '<div class="ic-overlay"><section class="ic-confirm" role="alertdialog" aria-label="Archive record"><h2>Archive '+E(st.deleteConfirm.name)+'?</h2><p>TrialAgents checks every accessible linked record before allowing this archive. History is retained; records are not hard-deleted.</p><div>'+btn('Cancel','cancel-delete','ic-outline')+btn('Review archive','confirm-delete','ic-primary')+'</div></section></div>';}
function detailsModal(){const d=st.drawer;if(!d)return '';let r=lookup(d.role,d.id);if(!r)return '';const extra=d.role==='investors'?'<h3>Linked professional contacts</h3>'+(!readAll('contacts').complete?'<p>Contact evidence incomplete.</p>':readAll('contacts').rows.filter(x=>x.data.investor_id===r.id).map(x=>'<div class="ic-detail-linked"><strong>'+E(x.data.name)+'</strong><span>'+E(x.data.title||x.data.channel||'Contact')+'</span>'+btn('Edit','edit:contacts:'+x.id,'ic-mini')+'</div>').join('')||'<p>No contacts linked yet.</p>')+btn('Add contact','contact-for:'+r.id,'ic-outline',!allow('contacts',['name']))+btn('Create opportunity','opportunity-for:'+r.id,'ic-outline',!allow('opportunities',['name'])):d.role==='opportunities'?btn('Add follow-up','task-for:'+r.id,'ic-primary',!allow('tasks',['name'])):'';
 return '<div class="ic-overlay"><section class="ic-drawer" role="dialog" aria-modal="true" aria-label="Record details"><div class="ic-drawer-head"><div><h2>'+E(r.data.name)+'</h2><p>Authorized record · version '+r.version+'</p></div>'+btn(icon('close',19),'close-drawer','ic-icon-btn')+'</div><div class="ic-drawer-body">'+Object.entries(r.data).filter(([k])=>k!=='archived').map(([k,v])=>'<div class="ic-detail-line"><span>'+E(k.replace(/_/g,' '))+'</span><strong>'+E(displayValue(d.role,k,v))+'</strong></div>').join('')+extra+'</div><div class="ic-drawer-foot">'+btn('Close','close-drawer','ic-outline')+btn('Edit','edit:'+d.role+':'+r.id,'ic-primary',!allow(d.role,['name']))+'</div></section></div>';}
const render={overview:overviewScreen,investors:investorsScreen,pipeline:pipelineScreen,interactions:interactionsScreen,followups:followupsScreen,research:researchScreen};
function sidebar(){const ordered=usableTabs.length?usableTabs:views.map(x=>x[0]);return '<aside class="ic-rail"><div class="ic-brand"><strong>Investor CRM</strong><span>Fundraising workspace</span></div><div class="ic-nav">'+ordered.map(id=>{const v=views.find(x=>x[0]===id);return btn(icon(id,18)+' <span>'+E(v?.[1]||id)+'</span>','nav:'+id,'ic-nav-link '+(st.route===id?'active':''),false,'aria-current="'+(st.route===id?'page':'false')+'"')}).join('')+'</div><div class="ic-rail-foot">Private investor relationships<br>TrialAgents-hosted access</div></aside>';}
if(st.editor)st.drawer=null;
const html='<div class="ic-shell">'+sidebar()+'<main class="ic-main"><div class="ic-topline"><span>'+E(layout.heading||cfg.heading||'Investor CRM')+'</span><div>'+pill('Internal','soft')+btn(icon('settings',17),'tracker:layout','ic-icon-btn',false,'aria-label="Layout settings"')+'</div></div>'+((st.notice)?'<div class="ic-notice" role="status">'+E(st.notice)+'</div>':'')+'<div class="ic-main-content">'+(render[st.route]||overviewScreen)()+'</div><footer class="ic-footer">Evidence-led fundraising · indicative interest is not signed capital · records save only after TrialAgents approval</footer></main></div>'+detailsModal()+editorModal()+deleteModal();
const css=typeof INVESTOR_CRM_CSS==='string'?INVESTOR_CRM_CSS:'';
return {html,css,state:st};
